import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error: {e}')

# Check for BeautifulSoup import
found_bs = False
for node in ast.walk(tree):
    if isinstance(node, ast.ImportFrom) and node.module == 'bs4':
        for name in node.names:
            if name.name == 'BeautifulSoup':
                found_bs = True

if not found_bs:
    raise AssertionError('Task 1: Missing from bs4 import BeautifulSoup')

# Check for BeautifulSoup() call with two arguments
found_soup = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == 'BeautifulSoup':
        if len(node.args) >= 2:
            found_soup = True

if not found_soup:
    raise AssertionError('Task 2: Missing BeautifulSoup() call with html_doc and parser')

# Check for find(id=...) call
found_find_id = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'find':
        # Check for keyword argument named 'id'
        for kw in node.keywords:
            if kw.arg == 'id':
                found_find_id = True

if not found_find_id:
    raise AssertionError('Task 3: Missing soup.find() with id parameter')

# Check for .text attribute access
found_text = False
for node in ast.walk(tree):
    if isinstance(node, ast.Attribute) and node.attr == 'text':
        found_text = True

if not found_text:
    raise AssertionError('Task 3-5: Missing .text attribute access')

# Check for find_all(class_=...) call
found_find_all_class = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == 'find_all':
        # Check for keyword argument named 'class_'
        for kw in node.keywords:
            if kw.arg == 'class_':
                found_find_all_class = True

if not found_find_all_class:
    raise AssertionError('Task 4: Missing soup.find_all() with class_ parameter')

# Check for for loop
found_for_loop = False
for node in ast.walk(tree):
    if isinstance(node, ast.For):
        found_for_loop = True

if not found_for_loop:
    raise AssertionError('Task 5: Missing for loop to iterate through product_names')

print('TEST_PASSED')
